"use client";

import "./input.css";
import { Input as BaseInput } from "@base-ui/react/input";
import type React from "react";
import { cn } from "tailwind-variants";

import { InputContext } from "./input.context";
import { inputVariants, type InputVariants } from "./input.variants";

export type InputProps = InputVariants & Omit<React.ComponentProps<typeof BaseInput>, "children">;

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/input/content.md
 */
export const InputRoot = ({
  className,
  size,
  variant,
  children: _children,
  dangerouslySetInnerHTML: _dangerouslySetInnerHTML,
  ...props
}: InputProps & { children?: React.ReactNode; dangerouslySetInnerHTML?: any }) => {
  const slots = inputVariants({ size, variant });

  return (
    <InputContext.Provider value={{ slots }}>
      <BaseInput className={cn(slots.root(), className)} {...props} />
    </InputContext.Provider>
  );
};

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/input/content.md
 */
export const Input = InputRoot;

/* eslint-disable perfectionist/sort-objects */

import { tv, type VariantProps } from "tailwind-variants";

export const inputVariants = tv({
  slots: {
    root: "input",
  },
  variants: {
    size: {
      sm: {
        root: "input--sm",
      },
      md: {
        root: "input--md",
      },
      lg: {
        root: "input--lg",
      },
    },
    variant: {
      default: {
        root: "input--default",
      },
      outline: {
        root: "input--outline",
      },
    },
  },
  defaultVariants: {
    size: "md",
    variant: "default",
  },
});

export type InputVariants = VariantProps<typeof inputVariants>;

"use client";

import { createContext, useContext } from "react";

import { inputVariants } from "./input.variants";

export type InputContext = {
  slots: ReturnType<typeof inputVariants>;
};

export const InputContext = createContext<InputContext | null>(null);

export const useInputContext = () => {
  const context = useContext(InputContext);
  return context ?? { slots: inputVariants() };
};

.input {
  @apply border-input bg-background placeholder:text-muted-foreground focus-visible:outline-ring data-invalid:border-destructive data-invalid:focus-visible:outline-destructive flex w-full rounded-md border text-sm shadow-xs transition-colors focus-visible:outline-2 disabled:cursor-not-allowed disabled:opacity-50;
}

.input--sm {
  @apply h-8 px-2 text-xs;
}

.input--md {
  @apply h-9 px-3 text-sm;
}

.input--lg {
  @apply h-10 px-4 text-base;
}

import { Input, InputRoot } from "./input";

/**
 * @see https://ui.awaiden.com/llms.mdx/docs/components/input/content.md
 */
export const InputContainer = {
  Root: InputRoot,
};

export { Input, InputRoot };

export type { InputProps } from "./input";
export { InputContext, useInputContext } from "./input.context";
export { type InputVariants, inputVariants } from "./input.variants";
